// RAII for dynamic memory (Modern C++ recommended)
class HeavyResource {};
std::unique_ptr<HeavyResource> ptr =
    std::make_unique<HeavyResource>();
// Resource cleanup guaranteed on scope exit.

// RAII for synchronization (Locks)
std::mutex access_mtx;
void protected_write() {
    // lock_guard ensures unlock() is called,
    // even if an exception is thrown.
    std::lock_guard<std::mutex> lock(access_mtx);
    // Critical section
}

// RAII for I/O Resources (File handles)
std::fstream config_file("settings.cfg", std::ios::in);
if (config_file.is_open()) {
    std::string line;
    std::getline(config_file, line);
}
// File handle automatically closed.

// Custom RAII Wrapper (Minimal Deleter concept)
struct FileCloser { void operator()(FILE* f) const { fclose(f); } };
std::unique_ptr<FILE, FileCloser> safe_file(
    fopen("temp.dat", "w"));
